const r = $json;
const deadline = r.artefacts?.frist?.deadline_iso;
const docs = r.artefacts?.required_documents ?? [];
const trace = r.tool_trace ?? [];
const checks = {
  live_gateway: r.gateway?.live === true,
  no_auto_send: r.gateway?.auto_send === false,
  structured_run_id: typeof r.agent_run_id === 'string' && r.agent_run_id.length > 8,
  deadline_correct: deadline === '2026-07-30',
  three_documents: docs.length === 3,
  human_review_gate: trace.some(t => t.tool === 'human_review_gate'),
};
const passed = Object.values(checks).every(Boolean);
if (!passed) throw new Error('Proof failed: ' + JSON.stringify(checks));
return [{json:{passed,checks,backend_mode:r.gateway.backend_mode,agent_run_id:r.agent_run_id,deadline,documents:docs.map(d=>d.name_de),tool_trace:trace.map(t=>t.tool),elapsed_ms:r.gateway.elapsed_ms,auto_send:r.gateway.auto_send}}];
